/* Scales a product's listed price to whichever litre size is picked,
   based on its own price-per-litre, then rounds to a clean ₦50. */
function priceForSize(product, sizeLabel) {
  const baseLitres = parseInt(getSize(product.name), 10) || 4;
  const litres = parseInt(sizeLabel, 10) || baseLitres;
  if (litres === baseLitres) return product.price;
  const perLitre = product.price / baseLitres;
  return Math.max(500, Math.round((perLitre * litres) / 50) * 50);
}

