/*  WHATSAPP ORDERING "BACKEND"                                        */
/*  No server needed — orders are handed off to the store's WhatsApp   */
/*  Business number as a pre-filled message, where the customer        */
/*  confirms details and pays directly with the team.                  */
/* ------------------------------------------------------------------ */

const WHATSAPP_NUMBER = "2348012345678"; // 0801 234 5678 in international format

function buildOrderMessage({ cart, subtotal, deliveryFee, total, shipping, payment, customer }) {
  const lines = [];
  lines.push("Hello MOJ Paint & Interiors! I'd like to place an order:");
  lines.push("");
  cart.forEach((c) => lines.push(`• ${c.name} (${c.brand.trim()}${c.sizeLabel ? `, ${c.sizeLabel}` : ""}${c.colorName ? `, ${c.colorName}` : ""}) × ${c.qty} — ${money(c.price * c.qty)}`));
  lines.push("");
  lines.push(`Subtotal: ${money(subtotal)}`);
  lines.push(`Delivery (${shipping === "express" ? "Express, 1–2 days" : "Standard, 2–4 days"}): ${money(deliveryFee)}`);
  lines.push(`Total: ${money(total)}`);
  lines.push("");
  lines.push(`Name: ${customer.fullName}`);
  lines.push(`Phone: ${customer.phone}`);
  lines.push(`Delivery Address: ${customer.address}, ${customer.city}, ${customer.state}`);
  lines.push(`Preferred Payment: ${payment === "paystack" ? "Card / Bank Transfer via Paystack" : "Cash on Delivery"}`);
  lines.push("");
  lines.push("Please confirm availability and how to complete payment. Thank you!");
  return lines.join("\n");
}

function whatsappOrderUrl(args) {
  return `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(buildOrderMessage(args))}`;
}

