function ProductImage({ product, className = "" }) {
  const [photoFailed, setPhotoFailed] = useState(false);
  const hasPhoto = !!product.photoUrl && !photoFailed;
  return (
    <div
      className={`relative overflow-hidden flex items-center justify-center ${hasPhoto ? "bg-white p-0" : "p-2"} ${className}`}
      style={
        hasPhoto
          ? {}
          : {
              background:
                "radial-gradient(circle at 28% 18%, rgba(255,255,255,0.4), transparent 45%), " +
                "repeating-radial-gradient(circle at 0 0, transparent 0, transparent 12px, rgba(255,255,255,0.07) 13px), " +
                "linear-gradient(155deg, #ced4db 0%, #9aa3ad 55%, #737f8c 100%)",
            }
      }
    >
      {hasPhoto ? (
        <img
          src={product.photoUrl}
          alt={product.name}
          className="w-full h-full object-cover"
          onError={() => setPhotoFailed(true)}
        />
      ) : (
        <>
          <PaintBucketArt brand={product.brand} finish={product.finish} size={getSize(product.name)} />
          <div className="absolute top-2 left-2 bg-white/95 backdrop-blur px-2 py-0.5 rounded text-[9px] font-bold tracking-wide text-[#0C1B33] shadow-sm">
            {product.brand.trim().toUpperCase()}
          </div>
        </>
      )}
    </div>
  );
}

