/* ------------------------------------------------------------------ */
/*  SHOP / ALL PAINTS PAGE                                             */
/* ------------------------------------------------------------------ */

function ShopPage({ nav, addToCart, query }) {
  const [cats, setCats] = useState([]);
  const [brands, setBrands] = useState([]);
  const [finishes, setFinishes] = useState([]);
  const [maxPrice, setMaxPrice] = useState(130000);
  const [page, setPage] = useState(1);
  const perPage = 8;

  const toggle = (arr, setArr, v) => setArr(arr.includes(v) ? arr.filter((x) => x !== v) : [...arr, v]);

  const filtered = useMemo(() => {
    return PRODUCTS.filter((p) => {
      if (cats.length && !cats.includes(p.category)) return false;
      if (brands.length && !brands.includes(p.brand.trim())) return false;
      if (finishes.length && !finishes.includes(p.finish)) return false;
      if (p.price > maxPrice) return false;
      if (query && !p.name.toLowerCase().includes(query.toLowerCase()) && !p.brand.toLowerCase().includes(query.toLowerCase())) return false;
      return true;
    });
  }, [cats, brands, finishes, maxPrice, query]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / perPage));
  const shown = filtered.slice((page - 1) * perPage, page * perPage);

  const countFor = (key, val) => PRODUCTS.filter((p) => (key === "category" ? p.category === val : key === "brand" ? p.brand.trim() === val : p.finish === val)).length;

  return (
    <div className="max-w-7xl mx-auto px-4 py-6 font-body">
      <div className="text-xs text-slate-400 mb-3 flex items-center gap-1">
        <button onClick={() => nav("home")} className="hover:text-[#B8863B]">Home</button> <ChevronRight size={12} /> <span>Shop</span>
      </div>
      <div className="flex items-center justify-between mb-5">
        <h1 className="text-2xl font-display font-bold text-[#0C1B33]">All Paints</h1>
        <span className="text-xs text-slate-400">Showing {shown.length ? (page - 1) * perPage + 1 : 0}–{(page - 1) * perPage + shown.length} of {filtered.length} results</span>
      </div>
      <div className="grid md:grid-cols-[220px_1fr] gap-6">
        <aside className="hidden md:block space-y-6">
          <FilterGroup title="Categories" items={CATEGORIES} selected={cats} onToggle={(v) => toggle(cats, setCats, v)} counter={(v) => countFor("category", v)} />
          <FilterGroup title="Brands" items={BRANDS} selected={brands} onToggle={(v) => toggle(brands, setBrands, v)} counter={(v) => countFor("brand", v)} />
          <FilterGroup title="Finish" items={FINISHES} selected={finishes} onToggle={(v) => toggle(finishes, setFinishes, v)} counter={(v) => countFor("finish", v)} />
          <div>
            <div className="font-display font-semibold text-sm text-[#0C1B33] mb-2">Price</div>
            <input type="range" min={5000} max={130000} value={maxPrice} onChange={(e) => setMaxPrice(Number(e.target.value))} className="w-full accent-[#B8863B]" />
            <div className="flex justify-between text-xs text-slate-400 mt-1"><span>₦5,000</span><span>{money(maxPrice)}</span></div>
          </div>
          <div className="flex gap-2">
            <button className="flex-1 text-white text-xs font-semibold py-2 rounded-md" style={{ background: NAVY }}>Filter</button>
            <button onClick={() => { setCats([]); setBrands([]); setFinishes([]); setMaxPrice(130000); }} className="flex-1 border border-slate-200 text-xs font-semibold py-2 rounded-md">Clear all</button>
          </div>
        </aside>
        <div>
          {shown.length === 0 ? (
            <div className="text-center py-20 text-slate-400">
              <SlidersHorizontal size={30} className="mx-auto mb-3" />
              No paints match these filters — try widening your search.
            </div>
          ) : (
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              {shown.map((p) => <ProductCard key={p.id} p={p} nav={nav} addToCart={addToCart} />)}
            </div>
          )}
          {totalPages > 1 && (
            <div className="flex items-center justify-center gap-1.5 mt-8">
              <button disabled={page === 1} onClick={() => setPage((p) => p - 1)} className="w-8 h-8 rounded-md border border-slate-200 flex items-center justify-center disabled:opacity-30"><ChevronLeft size={14} /></button>
              {Array.from({ length: totalPages }).map((_, i) => (
                <button key={i} onClick={() => setPage(i + 1)} className={`w-8 h-8 rounded-md text-xs font-semibold ${page === i + 1 ? "text-white" : "border border-slate-200 text-slate-500"}`} style={page === i + 1 ? { background: NAVY } : {}}>{i + 1}</button>
              ))}
              <button disabled={page === totalPages} onClick={() => setPage((p) => p + 1)} className="w-8 h-8 rounded-md border border-slate-200 flex items-center justify-center disabled:opacity-30"><ChevronRight size={14} /></button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function FilterGroup({ title, items, selected, onToggle, counter }) {
  return (
    <div>
      <div className="font-display font-semibold text-sm text-[#0C1B33] mb-2">{title}</div>
      <div className="space-y-1.5">
        {items.map((it) => (
          <label key={it} className="flex items-center gap-2 text-sm text-slate-600 cursor-pointer">
            <input type="checkbox" checked={selected.includes(it)} onChange={() => onToggle(it)} className="accent-[#B8863B]" />
            <span className="flex-1">{it}</span>
            <span className="text-xs text-slate-300">({counter(it)})</span>
          </label>
        ))}
      </div>
    </div>
  );
}

