function ProductPage({ product, nav, addToCart }) {
  const [qty, setQty] = useState(1);
  const [size, setSize] = useState(() => getSize(product?.name || ""));
  const [selectedColor, setSelectedColor] = useState(() => defaultColorFor(product?.colorTag));
  const [added, setAdded] = useState(false);
  const hasColorOptions = product && product.colorTag !== "-";
  const hasSizeOptions = product && !SIZELESS_CATEGORIES.includes(product.category);
  const currentPrice = product ? priceForSize(product, size) : 0;

  useEffect(() => {
    if (!product) return;
    setQty(1);
    setSize(getSize(product.name));
    setSelectedColor(defaultColorFor(product.colorTag));
    setAdded(false);
  }, [product && product.id]);

  if (!product) return null;
  return (
    <div className="max-w-7xl mx-auto px-4 py-6 font-body">
      <div className="text-xs text-slate-400 mb-4 flex items-center gap-1 flex-wrap">
        <button onClick={() => nav("home")} className="hover:text-[#B8863B]">Home</button> <ChevronRight size={12} />
        <button onClick={() => nav("shop")} className="hover:text-[#B8863B]">{product.category}</button> <ChevronRight size={12} />
        <span className="text-slate-500">{product.name}</span>
      </div>
      <div className="grid md:grid-cols-2 gap-10">
        <div className="grid grid-cols-[70px_1fr] gap-3">
          <div className="flex flex-col gap-2">
            {[0, 1, 2].map((i) => (
              <div key={i} className="border border-slate-200 rounded-md overflow-hidden"><ProductImage product={product} className="aspect-square" /></div>
            ))}
          </div>
          <div className="border border-slate-200 rounded-xl overflow-hidden bg-white">
            <ProductImage product={product} className="aspect-[4/5]" />
          </div>
        </div>
        <div>
          <h1 className="text-2xl font-display font-bold text-[#0C1B33]">{product.name}</h1>
          <div className="flex items-center gap-2 mt-2">
            <Stars rating={product.rating} />
            <span className="text-xs text-slate-400">({product.reviews} customer reviews)</span>
          </div>
          <div className="text-2xl font-display font-bold text-[#0C1B33] mt-3">
            {money(currentPrice)}
            {hasSizeOptions && <span className="text-xs font-normal text-slate-400 ml-2">for {size}</span>}
          </div>
          <p className="text-sm text-slate-500 mt-3 leading-relaxed">{product.desc}</p>

          {hasColorOptions && (
            <div className="mt-5">
              <div className="text-sm font-semibold text-[#0C1B33] mb-2">Color: <span className="font-normal text-slate-500">{selectedColor.name}</span></div>
              <div className="flex flex-wrap gap-2.5">
                {COLOR_PALETTE.map((c) => {
                  const isSelected = c.name === selectedColor.name;
                  return (
                    <button
                      key={c.name}
                      onClick={() => setSelectedColor(c)}
                      title={c.name}
                      aria-label={c.name}
                      className="w-8 h-8 rounded-full border-2 shadow flex items-center justify-center transition"
                      style={{ background: c.hex, borderColor: isSelected ? GOLD : "#fff", boxShadow: isSelected ? `0 0 0 2px ${GOLD}` : "0 1px 2px rgba(0,0,0,0.15)" }}
                    >
                      {isSelected && <CheckCircle2 size={14} className={c.name === "Brilliant White" || c.name === "Golden Yellow" ? "text-[#0C1B33]" : "text-white"} />}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {hasSizeOptions && (
            <div className="mt-5">
              <div className="text-sm font-semibold text-[#0C1B33] mb-2">Size (Litres)</div>
              <div className="flex gap-2">
                {SIZE_OPTIONS.map((s) => (
                  <button key={s} onClick={() => setSize(s)} className={`px-4 py-2 rounded-md text-sm font-semibold border ${size === s ? "text-white" : "border-slate-200 text-slate-600"}`} style={size === s ? { background: NAVY, borderColor: NAVY } : {}}>
                    {s}
                  </button>
                ))}
              </div>
              <div className="text-[11px] text-slate-400 mt-1.5">Price updates automatically for the litre size you pick.</div>
            </div>
          )}

          <div className="flex items-center gap-4 mt-6">
            <div className="flex items-center border border-slate-200 rounded-md">
              <button onClick={() => setQty((q) => Math.max(1, q - 1))} className="w-9 h-9 flex items-center justify-center"><Minus size={14} /></button>
              <span className="w-8 text-center text-sm font-semibold">{qty}</span>
              <button onClick={() => setQty((q) => q + 1)} className="w-9 h-9 flex items-center justify-center"><Plus size={14} /></button>
            </div>
            <button
              onClick={() => {
                addToCart(product, qty, hasColorOptions ? selectedColor : null, hasSizeOptions ? size : getSize(product.name), currentPrice);
                setAdded(true);
                setTimeout(() => setAdded(false), 1500);
              }}
              className="flex-1 text-[#0C1B33] font-bold py-2.5 rounded-md hover:opacity-90 transition flex items-center justify-center gap-2"
              style={{ background: `linear-gradient(120deg, ${GOLD_LIGHT}, ${GOLD})` }}
            >
              {added ? <><CheckCircle2 size={16} /> Added!</> : "Add to Cart"}
            </button>
          </div>
          <button onClick={() => nav("checkout")} className="w-full mt-2.5 border font-bold py-2.5 rounded-md hover:bg-slate-50" style={{ borderColor: NAVY, color: NAVY }}>Buy Now</button>
          <div className="flex items-center gap-4 mt-4 text-xs text-slate-400">
            <button className="flex items-center gap-1 hover:text-rose-500"><Heart size={14} /> Add to Wishlist</button>
            <button className="flex items-center gap-1 hover:text-[#B8863B]"><Share2 size={14} /> Share</button>
          </div>

          <div className="grid grid-cols-3 gap-3 mt-7 border-t border-slate-100 pt-5 text-center">
            <div><div className="text-[11px] text-slate-400">Coverage</div><div className="text-xs font-semibold text-[#0C1B33] mt-0.5">10–12 m²/litre</div></div>
            <div><div className="text-[11px] text-slate-400">Drying Time</div><div className="text-xs font-semibold text-[#0C1B33] mt-0.5">2–4 hours</div></div>
            <div><div className="text-[11px] text-slate-400">Finish</div><div className="text-xs font-semibold text-[#0C1B33] mt-0.5">{product.finish}</div></div>
          </div>
        </div>
      </div>

      <div className="mt-16">
        <h2 className="text-lg font-display font-bold text-[#0C1B33] mb-4">You may also like</h2>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {PRODUCTS.filter((p) => p.category === product.category && p.id !== product.id).slice(0, 4).map((p) => (
            <ProductCard key={p.id} p={p} nav={nav} addToCart={addToCart} />
          ))}
        </div>
      </div>
    </div>
  );
}

