function CartPage({ cart, updateQty, removeItem, nav }) {
  const subtotal = cart.reduce((s, c) => s + c.price * c.qty, 0);
  const delivery = cart.length ? 2500 : 0;
  const total = subtotal + delivery;
  return (
    <div className="max-w-7xl mx-auto px-4 py-6 font-body">
      <h1 className="text-2xl font-display font-bold text-[#0C1B33] mb-5">Your Cart ({cart.length})</h1>
      {cart.length === 0 ? (
        <div className="text-center py-24 text-slate-400">
          <ShoppingCart size={36} className="mx-auto mb-3" />
          Your cart is empty.
          <div><button onClick={() => nav("shop")} className="mt-4 text-white px-5 py-2.5 rounded-md text-sm font-semibold" style={{ background: NAVY }}>Continue Shopping</button></div>
        </div>
      ) : (
        <div className="grid md:grid-cols-[1fr_320px] gap-6">
          <div className="bg-white border border-slate-100 rounded-xl overflow-hidden">
            <div className="grid grid-cols-[1fr_auto_auto_auto] gap-4 px-4 py-3 text-xs font-semibold text-slate-400 border-b border-slate-100">
              <span>Product</span><span>Price</span><span>Quantity</span><span>Total</span>
            </div>
            {cart.map((item) => (
              <div key={item.lineId} className="grid grid-cols-[1fr_auto_auto_auto] gap-4 px-4 py-4 items-center border-b border-slate-50 last:border-0">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-14 rounded-md overflow-hidden shrink-0"><ProductImage product={item} className="w-full h-full" /></div>
                  <div>
                    <div className="text-sm font-semibold text-[#0C1B33] leading-snug">{item.name}</div>
                    {(item.colorName || item.sizeLabel) && (
                      <div className="flex items-center gap-1.5 mt-1 flex-wrap">
                        {item.colorName && (
                          <span className="flex items-center gap-1">
                            <span className="w-3 h-3 rounded-full border border-slate-200" style={{ background: (COLOR_PALETTE.find((c) => c.name === item.colorName) || {}).hex }} />
                            <span className="text-xs text-slate-500">{item.colorName}</span>
                          </span>
                        )}
                        {item.colorName && item.sizeLabel && <span className="text-xs text-slate-300">·</span>}
                        {item.sizeLabel && <span className="text-xs text-slate-500">{item.sizeLabel}</span>}
                      </div>
                    )}
                    <button onClick={() => removeItem(item.lineId)} className="text-xs text-rose-500 flex items-center gap-1 mt-1"><Trash2 size={11} /> Remove</button>
                  </div>
                </div>
                <span className="text-sm text-slate-600">{money(item.price)}</span>
                <div className="flex items-center border border-slate-200 rounded-md">
                  <button onClick={() => updateQty(item.lineId, item.qty - 1)} className="w-7 h-7 flex items-center justify-center"><Minus size={12} /></button>
                  <span className="w-7 text-center text-sm">{item.qty}</span>
                  <button onClick={() => updateQty(item.lineId, item.qty + 1)} className="w-7 h-7 flex items-center justify-center"><Plus size={12} /></button>
                </div>
                <span className="text-sm font-display font-bold text-[#0C1B33]">{money(item.price * item.qty)}</span>
              </div>
            ))}
          </div>
          <div className="bg-white border border-slate-100 rounded-xl p-5 h-fit">
            <h2 className="font-display font-bold text-[#0C1B33] mb-4">Order Summary</h2>
            <div className="flex justify-between text-sm text-slate-500 py-1.5"><span>Subtotal</span><span>{money(subtotal)}</span></div>
            <div className="flex justify-between text-sm text-slate-500 py-1.5"><span>Delivery Fee</span><span>{money(delivery)}</span></div>
            <div className="flex justify-between font-display font-bold text-[#0C1B33] pt-3 mt-2 border-t border-slate-100"><span>Total</span><span>{money(total)}</span></div>
            <button onClick={() => nav("checkout")} className="w-full mt-5 text-[#0C1B33] font-bold py-2.5 rounded-md hover:opacity-90 transition" style={{ background: `linear-gradient(120deg, ${GOLD_LIGHT}, ${GOLD})` }}>Proceed to Checkout</button>
            <div className="text-[10px] text-slate-400 mt-2 text-center flex items-center justify-center gap-1"><MessageCircle size={10} className="text-[#25D366]" /> Orders are confirmed &amp; paid for via WhatsApp</div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  CHECKOUT PAGE                                                       */
/* ------------------------------------------------------------------ */

function CheckoutPage({ cart, nav, clearCart }) {
  const [shipping, setShipping] = useState("standard");
  const [payment, setPayment] = useState("paystack");
  const [placed, setPlaced] = useState(false);
  const [customer, setCustomer] = useState({
    fullName: "John Chimuanya",
    phone: "0801 234 5678",
    email: "john@gmail.com",
    address: "15 University Road, Nsukka, Enugu State.",
    state: "Enugu",
    city: "Nsukka",
  });
  const setField = (key) => (e) => setCustomer((c) => ({ ...c, [key]: e.target.value }));

  const subtotal = cart.reduce((s, c) => s + c.price * c.qty, 0);
  const deliveryFee = shipping === "express" ? 6000 : 2500;
  const total = subtotal + deliveryFee;

  const orderArgs = { cart, subtotal, deliveryFee, total, shipping, payment, customer };

  const handlePlaceOrder = async () => {
    if (!cart.length) return;

    const orderPayload = {
      customer: customer.fullName,
      phone: customer.phone,
      email: customer.email,
      address: customer.address,
      city: customer.city,
      state: customer.state,
      payment,
      shipping,
      subtotal,
      deliveryFee,
      total,
      items: cart.map((item) => ({
        id: item.id,
        name: item.name,
        size: item.sizeLabel || getSize(item.name),
        color: item.colorName || defaultColorFor(item.colorTag || "White").name,
        qty: item.qty,
        price: item.price,
      })),
      status: "Pending",
      date: new Date().toLocaleDateString("en-GB"),
    };

    if (firebaseEnabled) {
      const saved = await saveOrderToDb(orderPayload);
      if (saved && saved.id) {
        ADMIN_ORDERS = [{ ...orderPayload, id: saved.id }, ...ADMIN_ORDERS];
      }
    }

    window.open(whatsappOrderUrl(orderArgs), "_blank");
    setPlaced(true);
  };

  if (placed) {
    return (
      <div className="max-w-md mx-auto px-4 py-24 text-center font-body">
        <div className="w-14 h-14 rounded-full bg-[#25D366] flex items-center justify-center mx-auto mb-4">
          <MessageCircle size={26} className="text-white" />
        </div>
        <h1 className="text-2xl font-display font-bold text-[#0C1B33]">Almost done!</h1>
        <p className="text-sm text-slate-500 mt-2">We've opened WhatsApp with your order details filled in. Just hit send to confirm availability and complete payment directly with our team.</p>
        <button onClick={() => window.open(whatsappOrderUrl(orderArgs), "_blank")} className="mt-6 w-full text-white px-6 py-2.5 rounded-md text-sm font-semibold flex items-center justify-center gap-2" style={{ background: "#25D366" }}>
          <MessageCircle size={16} /> Open WhatsApp Again
        </button>
        <button onClick={() => { clearCart(); nav("home"); setPlaced(false); }} className="mt-3 w-full border border-slate-200 text-[#0C1B33] px-6 py-2.5 rounded-md text-sm font-semibold">Back to Home</button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-6 font-body">
      <div className="flex items-center justify-between mb-5">
        <h1 className="text-2xl font-display font-bold text-[#0C1B33]">Checkout</h1>
        <span className="text-xs text-slate-400">Returning customer? <button className="font-semibold" style={{ color: GOLD }}>Login</button></span>
      </div>
      <div className="mb-5 flex items-start gap-2.5 bg-[#E9FBF0] border border-[#25D366]/30 rounded-lg px-4 py-3 text-xs text-[#0C1B33]">
        <MessageCircle size={16} className="text-[#25D366] shrink-0 mt-0.5" />
        <span>Orders are confirmed over <strong>WhatsApp</strong> — fill in your details below, then tap "Place Order" to send everything straight to our team and complete payment together.</span>
      </div>
      <div className="grid md:grid-cols-[1fr_1fr_320px] gap-6">
        <div className="bg-white border border-slate-100 rounded-xl p-5">
          <div className="flex items-center gap-2 font-display font-bold text-[#0C1B33] mb-4"><MapPin size={16} style={{ color: GOLD }} /> Delivery Information</div>
          <div className="space-y-3">
            <Field label="Full Name" value={customer.fullName} onChange={setField("fullName")} />
            <Field label="Phone Number" value={customer.phone} onChange={setField("phone")} />
            <Field label="Email Address" value={customer.email} onChange={setField("email")} />
            <Field label="Delivery Address" value={customer.address} onChange={setField("address")} />
            <div className="grid grid-cols-2 gap-3">
              <Field label="State" value={customer.state} onChange={setField("state")} />
              <Field label="City / Area" value={customer.city} onChange={setField("city")} />
            </div>
            <label className="flex items-center gap-2 text-xs text-slate-500 mt-1"><input type="checkbox" defaultChecked className="accent-[#B8863B]" /> Save this address</label>
          </div>
        </div>
        <div className="space-y-6">
          <div className="bg-white border border-slate-100 rounded-xl p-5">
            <div className="flex items-center gap-2 font-display font-bold text-[#0C1B33] mb-4"><Truck size={16} style={{ color: GOLD }} /> Shipping Method</div>
            <div className="space-y-2">
              <RadioRow name="ship" checked={shipping === "standard"} onChange={() => setShipping("standard")} label="Standard Delivery (2 – 4 days)" value={money(2500)} />
              <RadioRow name="ship" checked={shipping === "express"} onChange={() => setShipping("express")} label="Express Delivery (1 – 2 days)" value={money(6000)} />
            </div>
          </div>
          <div className="bg-white border border-slate-100 rounded-xl p-5">
            <div className="flex items-center gap-2 font-display font-bold text-[#0C1B33] mb-4"><CreditCard size={16} style={{ color: GOLD }} /> Payment Method</div>
            <div className="space-y-2">
              <RadioRow name="pay" checked={payment === "paystack"} onChange={() => setPayment("paystack")} label="Card / Bank Transfer via Paystack" />
              <RadioRow name="pay" checked={payment === "cod"} onChange={() => setPayment("cod")} label="Cash on Delivery" />
            </div>
            <p className="text-[10px] text-slate-400 mt-2.5">You'll finalize payment with our team on WhatsApp after sending your order.</p>
          </div>
        </div>
        <div className="bg-white border border-slate-100 rounded-xl p-5 h-fit">
          <h2 className="font-display font-bold text-[#0C1B33] mb-4">Order Summary</h2>
          {cart.map((c) => (
            <div key={c.lineId} className="flex justify-between text-xs text-slate-500 py-1"><span className="truncate pr-2">{c.name}{c.sizeLabel ? ` (${c.sizeLabel}${c.colorName ? `, ${c.colorName}` : ""})` : c.colorName ? ` (${c.colorName})` : ""} × {c.qty}</span><span>{money(c.price * c.qty)}</span></div>
          ))}
          <div className="flex justify-between text-sm text-slate-500 pt-3 mt-2 border-t border-slate-100"><span>Subtotal</span><span>{money(subtotal)}</span></div>
          <div className="flex justify-between text-sm text-slate-500 py-1"><span>Delivery Fee</span><span>{money(deliveryFee)}</span></div>
          <div className="flex justify-between font-display font-bold text-[#0C1B33] pt-2 border-t border-slate-100"><span>Total</span><span>{money(total)}</span></div>
          <button onClick={handlePlaceOrder} disabled={!cart.length} className="w-full mt-4 disabled:opacity-40 text-white font-bold py-2.5 rounded-md hover:opacity-90 transition flex items-center justify-center gap-2" style={{ background: "#25D366" }}>
            <MessageCircle size={16} /> Place Order via WhatsApp <span className="font-normal text-xs">{money(total)}</span>
          </button>
          <div className="text-[10px] text-slate-400 mt-2 text-center flex items-center justify-center gap-1"><ExternalLink size={10} /> Opens WhatsApp with your order pre-filled</div>
        </div>
      </div>
    </div>
  );
}

function Field({ label, defaultValue, value, onChange }) {
  const controlled = onChange !== undefined;
  return (
    <label className="block">
      <span className="text-xs font-medium text-slate-500">{label}</span>
      {controlled ? (
        <input value={value} onChange={onChange} className="w-full mt-1 border border-slate-200 rounded-md py-2 px-3 text-sm focus:outline-none focus:ring-2 focus:ring-[#B8863B]/40" />
      ) : (
        <input defaultValue={defaultValue} className="w-full mt-1 border border-slate-200 rounded-md py-2 px-3 text-sm focus:outline-none focus:ring-2 focus:ring-[#B8863B]/40" />
      )}
    </label>
  );
}

function RadioRow({ name, checked, onChange, label, value }) {
  return (
    <label className={`flex items-center justify-between border rounded-md px-3 py-2.5 cursor-pointer text-sm ${checked ? "bg-[#FBF3E4]" : "border-slate-200"}`} style={checked ? { borderColor: GOLD } : {}}>
      <span className="flex items-center gap-2 text-slate-600"><input type="radio" name={name} checked={checked} onChange={onChange} className="accent-[#B8863B]" /> {label}</span>
      {value && <span className="font-semibold text-[#0C1B33]">{value}</span>}
    </label>
  );
}

